        {
            obj.DialogBranches.Remove(keys);
            obj.DialogTopics.Remove(keys);
            obj.DialogTopics.ForEach(i => i.Remove(keys));
            obj.Scenes.Remove(keys);
        }
        
        public void Remove(
            IQuestInternal obj,
            HashSet<FormKey> keys,
            Type type,
            bool throwIfUnknown)
        {
            switch (type.Name)
            {
                case "IMajorRecord":
                case "MajorRecord":
                case "IFallout76MajorRecord":
                case "Fallout76MajorRecord":
                case "IMajorRecordGetter":
                case "IFallout76MajorRecordGetter":
                    if (!Quest_Registration.SetterType.IsAssignableFrom(obj.GetType())) return;
                    this.Remove(obj, keys);
                    break;
                case "ObjectProperty":
                case "IObjectPropertyGetter":
                case "IObjectProperty":
                    break;
                case "Condition":
                case "IConditionGetter":
                case "ICondition":
                case "ConditionGlobal":
                case "IConditionGlobalGetter":
                case "IConditionGlobal":
                case "ConditionFloat":
                case "IConditionFloatGetter":
                case "IConditionFloat":
                    break;
