        public static Quest_FieldIndex ConvertFieldIndex(Fallout76MajorRecord_FieldIndex index)
        {
            switch (index)
            {
                case Fallout76MajorRecord_FieldIndex.MajorRecordFlagsRaw:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.FormKey:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.VersionControl:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.EditorID:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.FormVersion:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.Version2:
                    return (Quest_FieldIndex)((int)index);
                case Fallout76MajorRecord_FieldIndex.Fallout76MajorRecordFlags:
                    return (Quest_FieldIndex)((int)index);
                default:
                    throw new ArgumentException($"Index is out of range: {index.ToStringFast()}");
            }
        }
        
