        public Quest Duplicate(
            IQuestGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Quest(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
