    internal partial class QuestSetterTranslationCommon : Fallout76MajorRecordSetterTranslationCommon
    {
        public new static readonly QuestSetterTranslationCommon Instance = new QuestSetterTranslationCommon();

        #region DeepCopyIn
        public void DeepCopyIn(
            IQuestInternal item,
            IQuestGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                item,
                rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
        }
        
        public void DeepCopyIn(
            IQuest item,
            IQuestGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.DURL) ?? true))
            {
                item.DURL = rhs.DURL;
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.DESC) ?? true))
            {
                item.DESC = rhs.DESC?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.Properties) ?? true))
            {
                errorMask?.PushIndex((int)Quest_FieldIndex.Properties);
                try
                {
                    if ((rhs.Properties != null))
                    {
                        item.Properties = 
                            rhs.Properties
                            .Select(r =>
                            {
                                return r.DeepCopy(
                                    errorMask: errorMask,
                                    default(TranslationCrystal));
                            })
                            .ToExtendedList<ObjectProperty>();
                    }
                    else
                    {
                        item.Properties = null;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.General) ?? true))
            {
                item.General = rhs.General.ToArray();
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.ENAM) ?? true))
            {
                item.ENAM = rhs.ENAM;
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.Location) ?? true))
            {
                item.Location.SetTo(rhs.Location.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.ExternalEvent) ?? true))
            {
                item.ExternalEvent.SetTo(rhs.ExternalEvent.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.QMCI) ?? true))
            {
                item.QMCI.SetTo(rhs.QMCI.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.TimeLimitGlobal) ?? true))
            {
                item.TimeLimitGlobal.SetTo(rhs.TimeLimitGlobal.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.EventTimeLimit) ?? true))
            {
                item.EventTimeLimit.SetTo(rhs.EventTimeLimit.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.StartupStageKeyword) ?? true))
            {
                item.StartupStageKeyword.SetTo(rhs.StartupStageKeyword.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.StartupLocation) ?? true))
            {
                item.StartupLocation.SetTo(rhs.StartupLocation.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.EventCurve) ?? true))
            {
                item.EventCurve.SetTo(rhs.EventCurve.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.UpdateConfigForm) ?? true))
            {
                item.UpdateConfigForm.SetTo(rhs.UpdateConfigForm.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Quest_FieldIndex.QSDD) ?? true))
            {
                errorMask?.PushIndex((int)Quest_FieldIndex.QSDD);
                try
                {
                    if(rhs.QSDD is {} rhsQSDD)
                    {
                        item.QSDD = rhsQSDD.DeepCopy(
                            errorMask: errorMask,
                            copyMask?.GetSubCrystal((int)Quest_FieldIndex.QSDD));
                    }
                    else
                    {
                        item.QSDD = default;
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
